const b = $input.first().json.body || $input.first().json;
const content = [];
if (b.image_base64) content.push(b.media_type==='application/pdf' ? {type:'document', source:{type:'base64', media_type:'application/pdf', data: b.image_base64}} : {type:'image', source:{type:'base64', media_type: b.media_type || 'image/jpeg', data: b.image_base64}});
content.push({type:'text', text: b.text || "Lis cette ordonnance."});
return [{ json: { payload: { model: 'claude-sonnet-4-6', max_tokens: 1200, system: b.system || 'Réponds en JSON.', messages: [{ role: 'user', content }] } } }];

const r = $input.first().json;
if (r.error) return [{ json: { actes: [], remarques: 'Erreur API Anthropic : ' + (r.error.message || JSON.stringify(r.error)) } }];
const txt = (r.content||[]).map(c=>c.text||'').join('').replace(/```json|```/g,'').trim();
let out;
try { out = JSON.parse(txt); } catch(e) { const m = txt.match(/\{[\s\S]*\}/); try { out = m ? JSON.parse(m[0]) : null; } catch(e2) { out = null; } }
if (!out) out = { actes: [], remarques: 'Réponse IA illisible : ' + (txt ? txt.slice(0,200) : JSON.stringify(r).slice(0,200)) };
return [{ json: out }];
